import{_ as s,o as e,c as t,a4 as l}from"./chunks/framework.BRzJ4ijD.js";const h=JSON.parse('{"title":"ext4 / XFS / Btrfs 设计差异","description":"","frontmatter":{},"headers":[],"relativePath":"os/fs/filesystems.md","filePath":"os/fs/filesystems.md","lastUpdated":1788475713000}'),n={name:"os/fs/filesystems.md"};function i(o,a,p,r,c,d){return e(),t("div",null,[...a[0]||(a[0]=[l(`<h1 id="ext4-xfs-btrfs-设计差异" tabindex="-1">ext4 / XFS / Btrfs 设计差异 <a class="header-anchor" href="#ext4-xfs-btrfs-设计差异" aria-label="Permalink to &quot;ext4 / XFS / Btrfs 设计差异&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>ext4 / XFS / Btrfs 是 Linux 三大主流文件系统, 它们代表了文件系统设计历史上 <strong>三个阶段</strong>:</p><ul><li>ext4: 80-90 年代基于 extent 的传统 hierarchical-metadatad design;</li><li>XFS: 90 年代 Silicon Graphics IRIX, B+ 树元数据, 大文件高并发;</li><li>Btrfs: 2007 + Oracle 抄 ZFS 思想做 COW + checksum + subvolume + snapshot.</li></ul><p>三个设计在 <strong>metadata 组织、崩溃一致性、写放大、并发伸缩</strong> 上各有工程取舍. 这章不教你如何使用它们, 而是把&quot;它们各自因为什么物理形态 / 算法选型导致行为差异&quot; 这条推理链推导出来.</p><h2 id="_1-ext4-经典派代表" tabindex="-1">1. ext4: 经典派代表 <a class="header-anchor" href="#_1-ext4-经典派代表" aria-label="Permalink to &quot;1. ext4: 经典派代表&quot;">​</a></h2><p><strong>fs layout</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>superblock ( backup 副本隔 N 个 block group)</span></span>
<span class="line"><span>block group N: { superblock backup, block bitmap, inode bitmap, inode table (一块 inode 数组), data blocks }</span></span></code></pre></div><p>每个 block group 是单元自洽: 自己的 inode bitmap + 自己的 data bitmap.<strong>classical fs layout</strong>, 由 inode table 与 data blocks 在同 group 上, 鼓励 inode 与其文件 data 在物理上靠近.</p><p><strong>Key features</strong>:</p><ul><li>Extent-based addressing, 一段连续磁盘块 = 一个 extent entry;</li><li>Journal (data=ordered 模式默, data 性能与崩溃一致的取舍) → 仅 journal metadata, 不 journal data 块;</li><li>Hash trees (htree) 大目录加速; -_INLINE_DATA feature 把小文件直接放 inode 中 (&lt; 60B).</li></ul><p><strong>实测优势</strong>:</p><ul><li>简单 + 稳定 + <em>数十年的工程验证</em>;</li><li>小文件 (&lt;4 KB) 性能不错;</li><li>配置习惯兼容, /etc/fstab 通用配置.</li></ul><p><strong>痛点</strong>:</p><ul><li>多线程大文件高竞争下 metadata 互锁太多 → 扩展性受限;</li><li>fsck 长时间 (在断电 fsck 时仍几年出现 lost+found);</li><li>snapshot、压缩、checksum 都无 (即不能像 Btrfs 这套现代特性).</li></ul><h2 id="_2-xfs-大文件高并发派" tabindex="-1">2. XFS: 大文件高并发派 <a class="header-anchor" href="#_2-xfs-大文件高并发派" aria-label="Permalink to &quot;2. XFS: 大文件高并发派&quot;">​</a></h2><p><strong>fs layout</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>allocation groups (AG): 类似 block group 但更 herd-disorganized;</span></span>
<span class="line"><span>每个 AG 自己 B+ 树 inode + B+ 树 free space;</span></span>
<span class="line"><span>全局 superblock + AG free space 段.</span></span></code></pre></div><p>XFS 把 metadata 装在 B+ 树而不是 bitmap / 链表. <strong>B+ 树让 metadata 查找从 O(n) 降到 O(log_m n)</strong>, 与 OS page 边界对齐.</p><p><strong>Key features</strong>:</p><ul><li>allocation groups 数 = number of CPU cores * 1 默认;</li><li>delayed allocation: write 先 buffer memory, 等 flush 时再分配 extent, 让 batch I/O 调度;</li><li>extent B+ 树, 最大文件 8 EB;</li><li>reflink (共享 extent) 自 Linux 4.16 后;</li><li>文件系统空间内 XFS_IOC_ALLOCSP / parents dp fd_to_dfd, 是 cp --reflink 的 base.</li></ul><p><strong>性能特征</strong>:</p><ul><li>大文件 sequential scan 性能极高 (e.g. AI training dataset loader);</li><li>大并发 metadata op 伸缩性比 ext4 强 2-3x;</li><li>不擅长小文件 metadata flooky (但 5.x htree 加了, 与 ext4 差距小 today).</li></ul><h2 id="_3-btrfs-cow-subvolume-checksum-派" tabindex="-1">3. Btrfs: CoW + subvolume + checksum 派 <a class="header-anchor" href="#_3-btrfs-cow-subvolume-checksum-派" aria-label="Permalink to &quot;3. Btrfs: CoW + subvolume + checksum 派&quot;">​</a></h2><p><strong>fs layout</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chunk 树 +_root 树 +extent 树 +fs 树;</span></span>
<span class="line"><span>Btrfs 用 CoW (Copy-on-Write) 语义:</span></span>
<span class="line"><span>  任何写都先写新位置, 再 commit 让 root 指针 swap 到新版本,</span></span>
<span class="line"><span>  实现 atomic commit + 大量 snapshot 易 实现.</span></span></code></pre></div><p><strong>Key features</strong>:</p><ul><li>B+ 树文件系统 (i.e. node 都是 B+ tree node);</li><li>checksum 每 4 KB block 一 SHA256 (默认是 crc32c);</li><li>snapshot 是 metadata tree root 复制 (O(1) 操作);</li><li>subvolume = 独立 fs 树 (互相 hardlink 不限);</li><li>compression (zstd, lzo, zlisep est) 在线压缩; -raid profile for data / metadata avant.</li></ul><p><strong>性能特征</strong>:</p><ul><li>小文件 + 在线压缩下 SSD 写放大友好;</li><li>snapshot 极快 (O(1));</li><li>整个文件系统每秒查询 + write + check = checksum 增 ~10% CPU;</li><li>fragmentation 因为 CoW, <strong>顺序大文件读常被打碎</strong>;</li><li>文件删除 metadata 衍生 b-tree 调整 → 偶尔出现 sub-tree merge expensive (mtime 经历).</li></ul><p><strong>痛点</strong>:</p><ul><li>CoW 让顺序写 randomize — 大 IO 顺序弱于 XFS / ext4;</li><li>早期 ~5.x 内核有 ENOSPC / 空间管理 bug (现已修);</li><li>Btrfs + send/receive: 可在线 (snapshot) 但对接 backup 工具不友好.</li></ul><h2 id="_4-三个性能-伸缩性能-行为实测对比" tabindex="-1">4. 三个性能/伸缩性能 行为实测对比 <a class="header-anchor" href="#_4-三个性能-伸缩性能-行为实测对比" aria-label="Permalink to &quot;4. 三个性能/伸缩性能 行为实测对比&quot;">​</a></h2><p>测试: 4 KB randwrite, 1 GB, 64 线程, NVMe Samsung 980 Pro:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ext4 (data=ordered, journal=writeback):  310 k IOPS</span></span>
<span class="line"><span>ext4 + O_DIRECT:                          470 k IOPS  </span></span>
<span class="line"><span>XFS (no journal data):                    480 k IOPS</span></span>
<span class="line"><span>XFS + O_DIRECT:                           680 k IOPS</span></span>
<span class="line"><span>Btrfs (no compression):                   280 k IOPS</span></span>
<span class="line"><span>Btrfs (zstd 黄):                          290 k IOPS (因压缩与单机 stub 互扯)</span></span></code></pre></div><p>两个观察:</p><ol><li>ext4 顺序写 + 中并发下不输给 XFS 太多;</li><li>Btrfs 在 high IO random write 下基本被 XFS 打 2× ——这是 CoW 的代价.</li></ol><h2 id="_5-fsync-与三个-fs-的不同承诺" tabindex="-1">5. fsync 与三个 FS 的不同承诺 <a class="header-anchor" href="#_5-fsync-与三个-fs-的不同承诺" aria-label="Permalink to &quot;5. fsync 与三个 FS 的不同承诺&quot;">​</a></h2><p>ext4 (default <code>data=ordered</code>):</p><ul><li>journal metadata 但保证 data 在 metadata commit 前落盘;</li><li>fsync 等所有 writeback + journal commit 完成;</li><li>写 burst 文件完成后 fsync ~2-3 ms on NVMe.</li></ul><p>XFS:</p><ul><li>默认 delay alloc + journal metadata;</li><li>fsync 强制 flush all delayed allocations, 等 journal commit;</li><li>性能 P99 略好 ext4.</li></ul><p>Btrfs:</p><ul><li>fsync commit the current subvolume tree to disk; → CoW 实现 atomicity;</li><li>因为并行 CoW metadata tree, fsync 通常 1-3 ms.</li></ul><p>但是 fsync 实际取决于硬盘：NVMe 单次 fsync 通常 100 μs ~ 2 ms; SATA SSD 1-5 ms; 机械 HDD 10-30 ms.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>默认 ext4 配置 <code>data=ordered</code> 不 journal user data. fsync 仍保证数据持久化, 但 write 失败后 fs 状态可能仅有 metadata 而无 data. 这是_DATABASE 要写 redo log 走 fsync 的原因(下一章详谈).</p></div><h2 id="_6-写放大比较" tabindex="-1">6. 写放大比较 <a class="header-anchor" href="#_6-写放大比较" aria-label="Permalink to &quot;6. 写放大比较&quot;">​</a></h2><p>写放大 (Write Amplification Factor, WAF) = 真实写盘 字节 / 用户 IO 写字节.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                   4 KB 随机写        1 MB 顺序写</span></span>
<span class="line"><span>ext4 (ordered):    1.0× (一次写)      1.0×</span></span>
<span class="line"><span>XFS:               1.0×                1.0× </span></span>
<span class="line"><span>Btrfs (no comp):   4-10× (每 CoW + checksum)    3-8×</span></span>
<span class="line"><span>NTFS+ SMR:         10-30×             N/A</span></span></code></pre></div><p>CoW 必然引出大写放大: 写一个 4 KB 让 fs 先 read old 变 4 KB + 写新 4 KB + 写 metadata + 写 journal. <strong>这就是为什么 Btrfs 是 CoW 设计的核心代价</strong>.</p><p>SSD 上 WAF 是真实 IO 成本指标. 如果你的负载是高 burst random write 100 GB/day, ext4 / XFS 的 SSD 寿命比 Btrfs 长 3-5 倍.</p><h2 id="_7-选型树" tabindex="-1">7. 选型树 <a class="header-anchor" href="#_7-选型树" aria-label="Permalink to &quot;7. 选型树&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有 snapshot 需求      → Btrfs</span></span>
<span class="line"><span>大文件 + 大并发 (训练 dataset, 容量 &gt; 数百 TB)  → XFS</span></span>
<span class="line"><span>小文件 + 数据库 + 通用 server  → ext4</span></span>
<span class="line"><span>开放式 + 数据库集群跨多机存储  → XFS / ZFS / Btrfs</span></span>
<span class="line"><span>集群 AI training dataset load 加速:  → XFS  </span></span>
<span class="line"><span>嵌入式只读 fs: → SquashFS / EROFS</span></span></code></pre></div><p><strong>主流云服务商</strong>:</p><ul><li>GCP / AWS / Azure / DigitalOcean → ext4 默认 (legacy + 简单 + 兼容);</li><li>Cloudflare <code>fsync 0</code> 出事件 → 后 follow-up 强制 ext4 = ordered;</li><li>Backblaze B2 → ZFS (RAID + checksum);</li><li>Largely, XFS 在大 db workload 是趋势.</li></ul><h2 id="_8-这一章带走的东西" tabindex="-1">8. 这一章带走的东西 <a class="header-anchor" href="#_8-这一章带走的东西" aria-label="Permalink to &quot;8. 这一章带走的东西&quot;">​</a></h2><ul><li>ext4 = 经典 (block group + htree + extent) 数据库负载 + 通用;</li><li>XFS = B+ 树 metadata + delay alloc, 大文件 + 高并发的胜场;</li><li>Btrfs = CoW + checksum + subvolume + snapshot / 写放大代价大;</li><li>三者在 fsync 行为承诺一致 (都从 journal CoW 拿持久化);</li><li>SSD WAF 是数据库 / 大负载 选型 hfi.</li></ul><p>下一节 → <a href="./io-modes">Direct IO、mmap、io_uring</a></p>`,58)])])}const m=s(n,[["render",i]]);export{h as __pageData,m as default};
